implementation:
int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req = NULL;
    struct smb2_write_response *resp = NULL;
    unsigned int total_len = 0;
    int i;

    if (!io_parms || !nbytes || !iov || n_vec <= 0) {
        return -EINVAL;
    }

    total_len = 0;
    for (i = 0; i < n_vec; i++) {
        if (iov[i].iov_len > (UINT_MAX - total_len)) {
            rc = -EOVERFLOW;
            goto out;
        }
        total_len += iov[i].iov_len;
    }

    req = kzalloc(sizeof(*req) + total_len, GFP_KERNEL);
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    req->hdr.ProtocolId = SMB2_PROTO_NUMBER;
    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(total_len);

    for (i = 0; i < n_vec; i++) {
        if (iov[i].iov_len > 0) {
            memcpy(req->Data + req->DataLength, iov[i].iov_base, iov[i].iov_len);
            req->DataLength += cpu_to_le32(iov[i].iov_len);
        }
    }

    rc = cifs_send_recv(io_parms->tcon->ses->server, &req->hdr, &resp, 0);
    if (rc) {
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);

out:
    kfree(req);
    kfree(resp);
    return rc;
}
